    return {'id': f'question-social-content-geo-bb-iv-4-{i}', 'subject': 'social', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-social-content-geo-bb-iv-4'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': SOURCES[0][0], 'sourceLocator': '公立國中社會科公開資料題；研究環境衝擊、資料比較、因果界線與公共決策的能力方向。', 'authoringNote': '依官方課綱 KG 與三個公立學校公開來源的題型／能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-09', 'lessonId': 'lesson-social-content-geo-bb-iv-4', 'examPatternRefs': refs, 'solutionStrategy': '先辨認環境衝擊的指標與尺度，再找控制變因、對照資料與結論界線。', 'solutionSteps': steps}

